// beacon-chain/state/fieldtrie/field_trie.go
func (f *FieldTrie) CopyTrie() *FieldTrie {
    if f.fieldLayers == nil {
        return &FieldTrie{field: f.field, dataType: f.dataType, reference: stateutil.NewRef(1), ...}
    }
    dstFieldTrie := make([][]*[32]byte, len(f.fieldLayers))
    for i, layer := range f.fieldLayers {
        dstFieldTrie[i] = make([]*[32]byte, len(layer))
        copy(dstFieldTrie[i], layer)  // copies *[32]byte pointers, not values
    }
    return &FieldTrie{
        fieldLayers:   dstFieldTrie,
        field:         f.field,
        dataType:      f.dataType,
        reference:     stateutil.NewRef(1),
        RWMutex:       new(sync.RWMutex),
        length:        f.length,
        numOfElems:    f.numOfElems,
        isTransferred: f.isTransferred,  // BUG: propagates poisoned state
    }
}

// FieldTrie.Empty() definition:
func (f *FieldTrie) Empty() bool {
    return f == nil || len(f.fieldLayers) == 0 || f.isTransferred
}

// TransferTrie sets isTransferred=true and zeros fieldLayers on source
func (f *FieldTrie) TransferTrie() *FieldTrie {
    f.isTransferred = true
    nTrie := &FieldTrie{fieldLayers: f.fieldLayers, ...}
    f.fieldLayers = nil
    return nTrie
}

